<?php $title = 'Meus dados — Felito'; $labels = ['access' => 'Acesso aos dados', 'correction' => 'Correção', 'deletion' => 'Exclusão', 'portability' => 'Portabilidade']; ?>
<section class="content-layout"><div class="page-heading"><div><div class="eyebrow"><span class="dot"></span>Conta e privacidade</div><h1>Meus dados</h1><p>Consulte e mantenha seus dados atualizados. A exclusão de registros é avaliada pela equipe para preservar o histórico operacional.</p></div><a class="button button-outline" href="/privacidade/exportar">Baixar meus dados</a></div>
  <div class="manager-grid"><section class="panel manager-form-panel"><h2>Dados da conta</h2><form method="post" class="form-stack"><?= csrfField() ?><input type="hidden" name="action" value="profile"><label for="name">Nome</label><input id="name" name="name" maxlength="120" required value="<?= e($profile['name']) ?>"><label for="email">E-mail</label><input id="email" name="email" type="email" maxlength="190" required value="<?= e($profile['email']) ?>"><label for="phone">Telefone</label><input id="phone" name="phone" type="tel" maxlength="30" required value="<?= e($profile['phone']) ?>"><button class="button button-primary" type="submit">Salvar correções</button></form>
    <h3>Consentimento registrado</h3><?php if ($consent): ?><p class="muted-copy">Termos <?= e($consent['terms_version']) ?> · Política <?= e($consent['privacy_version']) ?> · <?= e(localDateTime($consent['accepted_at'])) ?></p><?php else: ?><p class="muted-copy">Não há consentimento registrado para esta conta.</p><?php endif ?>
  </section><section class="panel manager-form-panel"><h2>Solicitar atendimento</h2><form method="post" class="form-stack"><?= csrfField() ?><input type="hidden" name="action" value="request"><label for="request_type">Tipo de solicitação</label><select id="request_type" name="request_type" required><?php foreach ($labels as $key => $label): ?><option value="<?= e($key) ?>"><?= e($label) ?></option><?php endforeach ?></select><label for="details">Detalhes (opcional)</label><textarea id="details" name="details" maxlength="1000" rows="4"></textarea><button class="button button-primary" type="submit">Enviar solicitação</button></form><p class="field-help">O acesso e a portabilidade também podem ser atendidos imediatamente pelo botão de download; a solicitação fica registrada para acompanhamento.</p></section></div>
  <section class="panel manager-list-panel"><h2>Solicitações anteriores</h2><?php if (!$requests): ?><p class="muted-copy">Nenhuma solicitação enviada.</p><?php else: ?><div class="movement-list"><?php foreach ($requests as $request): ?><article class="movement-row"><div class="movement-copy"><strong><?= e($labels[$request['request_type']] ?? $request['request_type']) ?> · <?= e($request['status']) ?></strong><p><?= e($request['details'] ?? '') ?></p><small><?= e(localDateTime($request['created_at'])) ?></small></div></article><?php endforeach ?></div><?php endif ?></section>
